layer.css:
[data-ryt="footer"] { color: rgb(152, 160, 171); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="button"] { color: rgb(152, 160, 171); background-color: rgb(27, 30, 35); border-top: 1px solid rgb(43, 48, 56); border-right: 1px solid rgb(43, 48, 56); border-bottom: 1px solid rgb(43, 48, 56); border-left: 1px solid rgb(43, 48, 56); border-radius: 50%; box-shadow: rgba(0, 0, 0, 0.08) 0px 2px 8px 0px; font-family: var(--ryt-font-body); font-weight: 600; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(152, 160, 171); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: rgb(140, 192, 242); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(140, 192, 242); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; line-height: 1.55; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-underline-offset: 3px }
[data-ryt="button"]:hover { color: #8cc0f2 }
